import{_ as o,o as t,c as r,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"OAuth 2.1 Provider Dogfood — dpop-refresh-rotation quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oauth21-provider-dpop-refresh.md","filePath":"quality-reports/auth/oauth21-provider-dpop-refresh.md"}'),a={name:"quality-reports/auth/oauth21-provider-dpop-refresh.md"};function i(s,e,n,c,h,l){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="oauth-2-1-provider-dogfood-—-dpop-refresh-rotation-quality-report" tabindex="-1">OAuth 2.1 Provider Dogfood — dpop-refresh-rotation quality report <a class="header-anchor" href="#oauth-2-1-provider-dogfood-—-dpop-refresh-rotation-quality-report" aria-label="Permalink to &quot;OAuth 2.1 Provider Dogfood — dpop-refresh-rotation quality report&quot;">​</a></h1><p>DPoP + refresh-rotation report for <code>examples/dogfood-oauth21-provider</code> Sub-Issue #866 (v1.21-3c).</p><p>Extends the endpoints-skeleton report (Sub-Issue #864 → <code>oauth21-provider-endpoints.md</code>) and the pkce-flow report (Sub-Issue #865 → <code>oauth21-provider-pkce.md</code>) with DPoP proof binding + refresh token rotation behavioural fidelity. The mock adapter (<code>@kiwa-test/auth</code>&#39;s <code>setupOAuth21Env</code> + <code>createAuthorizationServer</code>) covers every axis unconditionally; the real adapter (<code>oauth2-mock-server</code> via testcontainers) stays env-skipped through <code>KIWA_OAUTH21_ENV_MISSING</code> until Sub-Issue #867 ships the container image + wiring, so the real column shows the assertion contract rather than a green run.</p><h2 id="fidelity-axes-dpop-flow" tabindex="-1">Fidelity axes (dpop-flow) <a class="header-anchor" href="#fidelity-axes-dpop-flow" aria-label="Permalink to &quot;Fidelity axes (dpop-flow)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>RFC anchor</th><th>mock (<code>@kiwa-test/auth</code>)</th><th>real (oauth2-mock-server, gated by <code>OAUTH21_BOOTSTRAP=1</code>)</th><th>assertion</th></tr></thead><tbody><tr><td>1. DPoP header alg</td><td>RFC 9449 §4.2</td><td><code>parseDpopHeader</code> re-parses the compact JWT, refuses missing / comma-folded / non-<code>ES256</code> / non-<code>dpop+jwt</code> / non-EC-P256 headers with <code>header_missing</code> / <code>header_malformed</code> / <code>header_alg_refused</code> / <code>header_typ_refused</code> / <code>header_jwk_refused</code> — every rejection surfaces as <code>invalid_dpop_proof</code> at <code>/token</code></td><td>oauth2-mock-server refuses same downgrades with <code>invalid_dpop_proof</code> at the HTTP layer; discovery advertises <code>dpop_signing_alg_values_supported=[ES256]</code> only</td><td>Both drivers refuse every header downgrade before the AS is invoked. Valid proof mints <code>token_type=DPoP</code>; absent proof mints <code>token_type=Bearer</code> — the client can pick sender-constrained or plain bearer per request.</td></tr><tr><td>2. <code>htm</code> + <code>htu</code> binding</td><td>RFC 9449 §4.3</td><td><code>verifyDpopProofBinding</code> rejects wrong <code>htm</code> (uppercase HTTP method) with <code>payload_htm_mismatch</code> and wrong <code>htu</code> (absolute URL, no query / fragment) with <code>payload_htu_mismatch</code>; both surface as <code>invalid_dpop_proof</code> at <code>/token</code></td><td>oauth2-mock-server enforces same binding server-side, refuses with <code>invalid_dpop_proof</code></td><td>Proof is pinned to the exact request it rides on — a proof intended for <code>/introspect</code> cannot be replayed at <code>/token</code>, a proof crafted for a <code>GET</code> cannot be swapped into a <code>POST</code>.</td></tr><tr><td>3. <code>iat</code> skew tolerance</td><td>RFC 9449 §4.3</td><td>Kiwa AS <code>dpopIatSkewSec</code> window (default 60 s per <code>SetupOAuth21EnvOptions</code>); past + future proofs outside window refused with <code>payload_iat_skew</code> (<code>invalid_dpop_proof</code> on <code>/token</code>). Boundary case (exactly at window edge) still accepted</td><td>oauth2-mock-server enforces same window with same rejection code</td><td>Clock skew is bounded — a proof minted an hour ago is refused, but a proof at the boundary is accepted so a client with a slightly slow clock stays inside the window.</td></tr><tr><td>4. <code>jti</code> replay guard</td><td>RFC 9449 §4.3</td><td>Kiwa AS <code>seenJtis</code> registry — second use of a <code>jti</code> throws <code>payload_jti_replay</code>, missing <code>jti</code> throws <code>payload_jti_missing</code>. Distinct <code>jti</code>s pass consecutively (no false positives)</td><td>oauth2-mock-server same registry with same rejection code</td><td>Replay-defeated regardless of how the JWK / htm / htu look. Distinct <code>jti</code>s in consecutive proofs mint distinct token pairs — the AS distinguishes intentional retry from replay attack.</td></tr></tbody></table><h2 id="fidelity-axes-refresh-rotation" tabindex="-1">Fidelity axes (refresh-rotation) <a class="header-anchor" href="#fidelity-axes-refresh-rotation" aria-label="Permalink to &quot;Fidelity axes (refresh-rotation)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>RFC anchor</th><th>mock (<code>@kiwa-test/auth</code>)</th><th>real (oauth2-mock-server, gated by <code>OAUTH21_BOOTSTRAP=1</code>)</th><th>assertion</th></tr></thead><tbody><tr><td>1. rotation on use</td><td>RFC 9700 §2.2</td><td>Every <code>/token</code> <code>grant_type=refresh_token</code> success mints a fresh refresh_token whose <code>rotationCount = previous + 1</code>; kiwa AS drops the previous from the active map. 5-step chain observed to produce 6 distinct refresh_tokens</td><td>oauth2-mock-server rotates on every use with same <code>rotationCount</code> semantics</td><td>Every use invalidates the previous — a legitimate client that immediately refreshes twice would fail the second call, so the RP client library must track the current token carefully.</td></tr><tr><td>2. re-use detection</td><td>RFC 9700 §2.2.2</td><td>Reuse of a rotated refresh_token surfaces as <code>invalid_grant</code> with <code>kind=refresh_token_reused</code> (family torn down); <code>unknown_refresh_token</code> is a distinct kind so a caller can tell a stale token apart from a never-issued one. Reuse rejection applies regardless of which client presents the token — cross-client attempt refused too</td><td>oauth2-mock-server tears down the family with same kind separation</td><td>Reuse of a rotated token means one of the two holders (legitimate client or attacker) is unauthorized — the AS cannot tell which, so it tears down the whole chain. RFC 9700 §2.2.2 requires this.</td></tr><tr><td>3. expiry enforcement</td><td>RFC 6749 §5.1</td><td>Refresh token <code>expiresAt</code> boundary — exact boundary still valid; past-boundary refused with <code>invalid_grant</code> + <code>kind=refresh_token_expired</code>; freshly-minted token accepted immediately</td><td>oauth2-mock-server same expiry check with same kind</td><td>Expired refresh_token refused before rotation, no new tokens minted. Boundary case accepted so a client at exactly the expiry second still gets one grace refresh — helps clients with slightly slow clocks.</td></tr><tr><td>4. binding preservation</td><td>RFC 9449 §4.3</td><td>DPoP-bound refresh token inherits <code>jkt</code>; proof pinned to a different key refused with <code>invalid_dpop_proof</code> + <code>kind=dpop_binding_mismatch</code>; no proof on a bound token refused with <code>kind=dpop_binding_missing</code>. Rotated access_token carries <code>dpop_jkt</code> too so the resource server can verify without a fresh <code>/introspect</code></td><td>oauth2-mock-server enforces same DPoP binding on refresh</td><td>Rotation preserves sender-constrained binding — an attacker with an exfiltrated refresh_token cannot re-bind to their own key. The mock AS carries <code>dpopJkt</code> in the rotated <code>RefreshToken</code> record; the kiwa <code>rotateRefreshToken</code> primitive threads it through explicitly.</td></tr></tbody></table><h2 id="dpop-guard-implementation-notes" tabindex="-1">DPoP guard implementation notes <a class="header-anchor" href="#dpop-guard-implementation-notes" aria-label="Permalink to &quot;DPoP guard implementation notes&quot;">​</a></h2><ul><li><code>src/lib/dpop.ts</code> re-exports the kiwa primitives (<code>parseDpopProof</code>, <code>verifyDpopProof</code>, <code>computeJkt</code>, <code>createMockDpopJwk</code>) so the dogfood app never imports directly from <code>@kiwa-test/auth</code> in the app layer. Downstream Sub-Issues can swap the kiwa helper for a different implementation without touching the route handlers.</li><li><code>DpopValidationError.kind</code> is the SSOT for the OAuth 2.1 error code mapping. <code>mapDpopKindToTokenCode</code> in <code>src/lib/hono-app.ts</code> maps every rejection kind to <code>invalid_dpop_proof</code> — the exhaustive switch forces the caller to decide which OAuth code to emit when a new kind is added.</li><li><code>parseDpopHeader</code> runs at the HTTP boundary (Hono <code>/token</code> handler reads the <code>DPoP</code> header, normalises the value, parses it). Absent header → <code>token_type=Bearer</code> output; present header → parsed proof forwarded into the adapter as <code>TokenRequest.dpop</code>. Absent header is not an error unless the refresh_token is DPoP-bound (kiwa AS catches that case).</li><li><code>classifyDpopAsError</code> in <code>src/lib/hono-app.ts</code> classifies kiwa AS-side rejection messages from <code>verifyDpopProof(...)</code> — the AS invokes the verifier inside <code>handleAuthorizationCode</code> + <code>handleRefreshToken</code>, so the rejection surfaces at the outer <code>adapter.token(...)</code> call with a <code>verifyDpopProof:</code> prefix. The classifier keeps the switch in one place so route handlers do not grep the underlying error string.</li></ul><h2 id="refresh-rotation-guard-implementation-notes" tabindex="-1">Refresh-rotation guard implementation notes <a class="header-anchor" href="#refresh-rotation-guard-implementation-notes" aria-label="Permalink to &quot;Refresh-rotation guard implementation notes&quot;">​</a></h2><ul><li><code>src/lib/refresh-rotation.ts</code> re-exports the kiwa <code>rotateRefreshToken</code> primitive as <code>rotateAndMint</code> — the wrapper normalises the failure surface (<code>refresh_token_revoked</code> when the previous token is already invalid) so downstream code never has to grep on the kiwa error string.</li><li><code>classifyRefreshTokenError</code> in <code>src/lib/refresh-rotation.ts</code> is the SSOT for classifying kiwa AS <code>/token</code> <code>grant_type=refresh_token</code> rejections into a stable <code>RefreshRotationRejectionKind</code>. The <code>mapRotationKindToTokenCode</code> helper in <code>src/lib/hono-app.ts</code> translates each kind to <code>invalid_grant</code> (RFC 6749 §5.2) or <code>invalid_dpop_proof</code> (RFC 9449 §5.2 for binding failures).</li><li><code>RefreshRotationError.kind</code> distinguishes reuse (<code>refresh_token_reused</code> — family compromise) from unknown token (<code>unknown_refresh_token</code> — never-issued or expired-and-purged). Route handlers surface the kind in the response body so the RP client library can tell &quot;your token expired&quot; apart from &quot;someone is replaying your token&quot;.</li><li>Rotation itself lives inside the kiwa AS (<code>handleRefreshToken</code> in <code>authorization-server.ts</code>); the wrapper is a classifier + type re-export, not a duplicate rotation engine.</li></ul><h2 id="real-adapter-scaffolding" tabindex="-1">Real-adapter scaffolding <a class="header-anchor" href="#real-adapter-scaffolding" aria-label="Permalink to &quot;Real-adapter scaffolding&quot;">​</a></h2><ul><li>The env-skip contract established in Sub-Issue #865 carries forward unchanged — <code>startOAuth2MockServer()</code> in <code>src/adapters/real.ts</code> still routes through <code>OAUTH21_BOOTSTRAP=1</code> + optional <code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code>. Sub-Issue #867 will replace the URL-driven branch with a testcontainers <code>GenericContainer</code> once the workspace commits the <code>testcontainers</code> dependency.</li><li><code>makeRealAdapter</code> continues to record every failed method call with <code>errorKind=&#39;KIWA_OAUTH21_ENV_MISSING&#39;</code> so the fidelity report captures &quot;environment absent&quot; rather than &quot;assertion failed&quot; — the dpop-flow + refresh-rotation harnesses both add env-skip smoke tests that pin this behaviour.</li></ul><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/dpop-flow.spec.ts</code> — 27 tests, split into five describe blocks: <ul><li><code>axis 1 — DPoP header alg (RFC 9449 §4.2)</code> — 12 tests covering <code>DPOP_TYP</code> / <code>DPOP_ALG</code> constants + <code>parseDpopHeader</code> rejection paths (missing / comma-fold / malformed / typ / alg / jwk) + <code>assertDpopHeaderShape</code> happy path + <code>/token</code> <code>token_type=DPoP</code> mint + <code>/token</code> <code>token_type=Bearer</code> mint + <code>/token</code> alg refusal.</li><li><code>axis 2 — htm + htu binding (RFC 9449 §4.3)</code> — 5 tests covering <code>verifyDpopProofBinding</code> happy path + htm mismatch + htu mismatch + <code>/token</code> htu rejection + <code>/token</code> htm rejection.</li><li><code>axis 3 — iat skew tolerance (RFC 9449 §4.3)</code> — 4 tests covering exact boundary + past skew + future skew + <code>/token</code> far-past rejection.</li><li><code>axis 4 — jti replay guard (RFC 9449 §4.3)</code> — 4 tests covering <code>verifyDpopProofBinding</code> replay rejection + missing jti rejection + <code>/token</code> replay rejection + <code>/token</code> distinct-jti happy path.</li><li><code>real adapter — DPoP env-skip contract</code> — 1 test validating <code>KIWA_OAUTH21_ENV_MISSING</code> gate on the DPoP path.</li></ul></li><li><code>tests/refresh-rotation.spec.ts</code> — 20 tests, split into five describe blocks: <ul><li><code>axis 1 — rotation on use (RFC 9700 §2.2)</code> — 4 tests covering fresh refresh_token mint + <code>rotationCount</code> increment + 5-step chain + <code>rotateAndMint</code> behaviour.</li><li><code>axis 2 — re-use detection (RFC 9700 §2.2.2)</code> — 6 tests covering reuse rejection + unknown token rejection + cross-client reuse rejection + <code>classifyRefreshTokenError</code> mapping + <code>rotateAndMint</code> revoked-token rejection.</li><li><code>axis 3 — expiry enforcement (RFC 6749 §5.1)</code> — 4 tests covering past-boundary rejection + boundary acceptance + fresh acceptance + classifier mapping.</li><li><code>axis 4 — binding preservation (RFC 9449 §4.3)</code> — 5 tests covering DPoP-bound refresh happy path + wrong-key rejection + missing-proof rejection + classifier mappings.</li><li><code>real adapter — refresh-rotation env-skip contract</code> — 1 test validating <code>KIWA_OAUTH21_ENV_MISSING</code> gate on the refresh path.</li></ul></li></ul><p>Total: 93 tests across the endpoints-skeleton (15) + pkce-flow (31) + dpop-flow (27) + refresh-rotation (20) specs. All passing on the mock adapter; real assertions gated by <code>OAUTH21_BOOTSTRAP=1</code>.</p><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock adapter; every axis runs unconditionally.</li><li><code>OAUTH21_BOOTSTRAP=1</code> — opt-in for real ceremonies. Combined with <code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code> the harness can drive an externally-managed oauth2-mock-server (docker-compose flow).</li><li>Without <code>OAUTH21_BOOTSTRAP=1</code>, the real adapter&#39;s <code>discovery()</code> still returns a valid metadata document (static shape derived from <code>issuer</code>); every other method reports <code>KIWA_OAUTH21_ENV_MISSING</code>.</li></ul><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li>Sub-Issue #867 (<code>revocation-fidelity-release-gate</code>) — Revocation cascade (revoke access → refresh family torn down) + real vs mock fidelity harness (5 endpoints × 4-6 axes = 24 axis grid) + release gate 7-axis integrated report + testcontainers dependency commit. The DPoP + refresh-rotation harness will merge into the revocation harness so a single <code>refresh_token</code> revocation invalidates the whole DPoP-bound family (RFC 9700 §2.2.2 + RFC 9449 §4.3 combined).</li></ul>',20)])])}const f=o(a,[["render",i]]);export{u as __pageData,f as default};
